type Query {
  books: [Book!]!
  book(id: ID!): Book
}

type Book {
  id: ID!
  title: String!
  author: String!
  price: Float!
}

type Mutation {
  addBook(title: String!, author: String!, price: Float!): Book!
}

[GraphQLDescription("A book in the catalog.")]
public class Book
{
    [GraphQLDescription("Unique identifier.")]
    public int Id { get; set; }

    public string Title { get; set; }
    public string Author { get; set; }
    public decimal Price { get; set; }
}

public class Query
{
    [GraphQLDescription("Get all books.")]
    [UsePaging]
    public IEnumerable<Book> GetBooks() => _repository.GetAll();
}
